try {
  const data = $input.item.json.body || $input.item.json;
  const nombre = data.nombre || 'No especificado';
  const telefono = data.telefono || 'No especificado';
  const servicio = data.servicio || 'General';
  const etapa = data.etapa || 'Nuevo Lead';

  const mensaje = `🚨 *NUEVO LEAD - UROCLINIC* 🚨\n\n` +
    `👤 *Nombre:* ${nombre}\n` +
    `📱 *Teléfono:* ${telefono}\n` +
    `💡 *Servicio:* ${servicio}\n` +
    `📊 *Etapa:* ${etapa}\n\n` +
    `⚡ *¡Atender de inmediato!*`;

  return [{ json: { chat_id: 'TU_CHAT_ID', text: mensaje, parse_mode: 'Markdown' } }];
} catch (error) {
  return [{ json: { chat_id: 'TU_CHAT_ID', text: `⚠️ Error procesando lead: ${error.message}`, parse_mode: 'Markdown' } }];
}
